import sys
import time
from watchdog.observers import Observer
from watchdog.events import FileSystemEventHandler

LOG_PATH = "/var/log/watcher.log"
WATCHED_PATH = "/watched"

class WatchHandler(FileSystemEventHandler):
    def on_created(self, event):
        if not event.is_directory:
            self.log(f"File created: {event.src_path}")

    @staticmethod
    def log(message):
        # Open per event so external truncation/rotation of the log is picked up.
        with open(LOG_PATH, "a", encoding="utf-8") as log_file:
            log_file.write(message + "\n")
            log_file.flush()

if __name__ == "__main__":
    import os
    os.makedirs(WATCHED_PATH, exist_ok=True)

    event_handler = WatchHandler()
    observer = Observer()
    observer.schedule(event_handler, path=WATCHED_PATH, recursive=False)
    observer.start()

    stopping = {"flag": False}

    def handle_signal(signum, frame):
        stopping["flag"] = True

    signal.signal(signal.SIGTERM, handle_signal)
    signal.signal(signal.SIGINT, handle_signal)

    try:
        while not stopping["flag"]:
            time.sleep(1)
    finally:
        observer.stop()
        observer.join()
